//! Port of `tests/unit/server/shell-integration.test.ts`, plus golden files
//! generated by the TypeScript implementation.

use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};

use muxus_local::Platform;
use muxus_local::shell_integration::{
    BASH_INIT, SHELL_CWD_REPORT, ShellIntegration, ZSHENV, ZSHRC, integration_dir,
    shell_integration, write_integration_files,
};

fn written() -> (tempfile::TempDir, PathBuf) {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path().join("muxus-shellint");
    write_integration_files(&root).unwrap();
    (dir, root)
}

fn read(root: &Path, rel: &str) -> String {
    fs::read_to_string(root.join(rel)).unwrap()
}

fn env(pairs: &[(&str, &str)]) -> HashMap<String, String> {
    pairs
        .iter()
        .map(|(key, value)| (key.to_string(), value.to_string()))
        .collect()
}

#[test]
fn generated_files_match_the_typescript_output_byte_for_byte() {
    let (_dir, root) = written();
    let golden = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/shell-integration");
    for rel in ["zsh/.zshenv", "zsh/.zshrc", "bash-init.bash"] {
        assert_eq!(read(&root, rel), read(&golden, rel), "{rel} differs");
    }
    assert!(ZSHRC.contains(SHELL_CWD_REPORT));
    assert!(BASH_INIT.contains(SHELL_CWD_REPORT));
    assert_eq!(read(&golden, "zsh/.zshenv"), ZSHENV);
}

#[cfg(unix)]
#[test]
fn writes_private_directories_and_readable_files() {
    use std::os::unix::fs::PermissionsExt;
    let (_dir, root) = written();
    let mode = |path: PathBuf| fs::metadata(path).unwrap().permissions().mode() & 0o777;
    assert_eq!(mode(root.join("zsh")), 0o700);
    assert_eq!(mode(root.join("bash-init.bash")), 0o644);
    // Idempotent.
    write_integration_files(&root).unwrap();
}

#[test]
fn emits_osc_133_command_reports_from_the_zsh_shim() {
    let (_dir, root) = written();
    let zshrc = read(&root, "zsh/.zshrc");
    assert!(zshrc.contains(r"\e]133;D;%s\a"));
    assert!(zshrc.contains(r"\e]133;C\a"));
    assert!(zshrc.contains(r"\e]133;P;Cwd=%s\a"));
    assert!(zshrc.contains("__muxus_report_cwd"));
    assert!(zshrc.contains("add-zsh-hook precmd"));
    assert!(zshrc.contains("add-zsh-hook preexec"));
}

#[test]
fn sources_the_user_zsh_startup_files_before_hooking() {
    let (_dir, root) = written();
    assert!(read(&root, "zsh/.zshenv").contains("${ZDOTDIR:-$HOME}/.zshenv"));
    assert!(read(&root, "zsh/.zshrc").contains("${ZDOTDIR:-$HOME}/.zshrc"));
}

#[test]
fn reports_via_ps0_and_prompt_command_in_the_bash_shim() {
    let (_dir, root) = written();
    let bash = read(&root, "bash-init.bash");
    assert!(bash.contains("\"$HOME/.bashrc\""));
    assert!(bash.contains(r#"PS0="\[\e]133;C\a\]${PS0-}""#));
    assert!(
        bash.contains(r#"PROMPT_COMMAND="__muxus_prompt_mark${PROMPT_COMMAND:+;$PROMPT_COMMAND}""#)
    );
    assert!(bash.contains(r"\e]133;P;Cwd=%s\a"));
}

#[test]
fn redirects_zsh_through_the_shim_zdotdir() {
    let (_dir, root) = written();
    let result = shell_integration(
        "/usr/bin/zsh",
        &HashMap::new(),
        Some(&root),
        Platform::Linux,
    );
    assert!(result.args.is_empty());
    assert_eq!(
        result.env,
        env(&[("ZDOTDIR", root.join("zsh").to_str().unwrap())])
    );
}

#[test]
fn carries_the_user_zdotdir_through_for_the_shim_to_restore() {
    let (_dir, root) = written();
    let result = shell_integration(
        "/bin/zsh",
        &env(&[("ZDOTDIR", "/home/u/.config/zsh")]),
        Some(&root),
        Platform::Linux,
    );
    assert_eq!(
        result.env,
        env(&[
            ("ZDOTDIR", root.join("zsh").to_str().unwrap()),
            ("MUXUS_USER_ZDOTDIR", "/home/u/.config/zsh"),
        ])
    );
}

#[test]
fn starts_bash_with_the_init_file_shim() {
    let (_dir, root) = written();
    let result = shell_integration("/bin/bash", &HashMap::new(), Some(&root), Platform::Linux);
    assert_eq!(
        result.args,
        vec![
            "--init-file".to_string(),
            root.join("bash-init.bash").to_string_lossy().into_owned()
        ]
    );
    assert!(result.env.is_empty());
}

#[test]
fn prefixes_the_native_cmd_prompt_with_a_live_windows_cwd_report() {
    let result = shell_integration(
        r"C:\Windows\System32\cmd.exe",
        &env(&[("PROMPT", "$S$P$G")]),
        None,
        Platform::Windows,
    );
    assert!(result.args.is_empty());
    assert_eq!(
        result.env,
        env(&[("PROMPT", r"$E]133;P;CwdRaw=$P$E\$S$P$G")])
    );
}

#[test]
fn uses_the_standard_visible_cmd_prompt_when_none_was_configured() {
    assert_eq!(
        shell_integration("cmd.exe", &HashMap::new(), None, Platform::Windows).env,
        env(&[("PROMPT", r"$E]133;P;CwdRaw=$P$E\$P$G")])
    );
}

#[test]
fn leaves_other_windows_shells_untouched() {
    assert_eq!(
        shell_integration("powershell.exe", &HashMap::new(), None, Platform::Windows),
        ShellIntegration::default()
    );
}

#[test]
fn leaves_other_shells_untouched() {
    let (_dir, root) = written();
    assert_eq!(
        shell_integration(
            "/usr/bin/fish",
            &HashMap::new(),
            Some(&root),
            Platform::Linux
        ),
        ShellIntegration::default()
    );
}

#[test]
fn degrades_to_no_integration_when_the_shim_dir_is_unavailable() {
    assert_eq!(
        shell_integration("/bin/zsh", &HashMap::new(), None, Platform::Linux),
        ShellIntegration::default()
    );
}

#[test]
fn keeps_the_shims_in_the_cache_directory() {
    let home = Path::new("/home/u");
    assert_eq!(
        integration_dir(&HashMap::new(), home),
        PathBuf::from("/home/u/.cache/muxus/shell-integration")
    );
    assert_eq!(
        integration_dir(&env(&[("XDG_CACHE_HOME", "/tmp/cache")]), home),
        PathBuf::from("/tmp/cache/muxus/shell-integration")
    );
}
